const row = items[0]?.json ?? {};

const safe = (value, fallback = '') => String(value ?? fallback).trim();
const compactObject = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const parseJsonObject = (value) => {
  if (!value) return {};
  if (typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string') return {};
  try {
    const parsed = JSON.parse(value);
    return compactObject(parsed);
  } catch (_error) {
    return {};
  }
};
const arrayCount = (value) => Array.isArray(value) ? value.length : 0;
const isPlaceholder = (value) => {
  const text = safe(value);
  return !text || /^__.*__$/.test(text) || text === '__PENDIENTE__';
};
const provider = safe($env.AI_PROVIDER, 'nvidia').toLowerCase();
const model = safe($env.AI_DIRECT_API_MODEL);
const requestPath = safe($env.AI_DIRECT_API_PATH, '/chat/completions');
const usesChatCompletions = requestPath.includes('/chat/completions');
const apiMode = usesChatCompletions ? 'chat_completions' : 'responses';
const baseUrl = safe($env.AI_DIRECT_API_BASE_URL, 'https://api.openai.com/v1').replace(/\/+$/, '');
const directApiKey = safe($env.AI_DIRECT_API_KEY);
const timeoutMs = Number($env.AI_DIRECT_API_TIMEOUT_MS || 15000);
const commercialContext = parseJsonObject(row.commercial_context);
const commercialContextCounts = {
  catalog_items: arrayCount(commercialContext.catalog_items),
  conditions: arrayCount(commercialContext.conditions),
  faqs: arrayCount(commercialContext.faqs),
  objections: arrayCount(commercialContext.objections),
  available_slots: arrayCount(commercialContext.available_slots),
};
const hasCommercialContext = Object.values(commercialContextCounts).some((count) => count > 0);

const currentContext = {
  message_current: safe(row.message_current, safe(row.text_body)),
  message_type: safe(row.message_type, 'text'),
  conversation_status: safe(row.conversation_status_code, safe(row.conversation_status)),
  current_step: safe(row.current_step),
  existing_fields: {
    service: safe(row.service),
    city: safe(row.city),
    requirement: safe(row.requirement),
  },
  previous_lead: compactObject(row.previous_lead),
  recent_messages: Array.isArray(row.recent_messages) ? row.recent_messages.slice(-8) : [],
  commercial_context: commercialContext,
  commercial_context_counts: commercialContextCounts,
};

const responseSchema = {
  type: 'object',
  additionalProperties: false,
  required: [
    'intent',
    'lead_quality',
    'service',
    'city',
    'requirement',
    'missing_fields',
    'confirmation_status',
    'should_create_lead',
    'needs_confirmation',
    'confidence',
    'reply_text',
    'clickup_summary',
    'customer_type',
    'lead_class',
    'modality',
    'diagnostic_datos',
    'commercial_missing_fields',
    'objection_detected',
    'escalation_area',
    'executive_summary',
  'explicitly_mentioned_fields',
  ],
  properties: {
    intent: {
      type: 'string',
      enum: [
        'greeting',
        'quote_request',
        'provide_info',
        'price_inquiry',
        'delivery_inquiry',
        'installation_inquiry',
        'stock_inquiry',
        'payment_method',
        'payment_proof',
        'invoice_request',
        'warranty_inquiry',
        'complaint',
        'post_sale',
        'reschedule_delivery',
        'reschedule_installation',
        'b2b_request',
        'purchase_order',
        'debris_removal',
        'plant_pickup',
        'competitor_comparison',
        'discount_request',
        'returning_customer',
        'review',
        'talk_to_human',
        'correction',
        'confirmation_yes',
        'confirmation_no',
        'new_request',
        'continue_previous',
        'irrelevant',
        'unknown',
      ],
      description: 'Intencion principal del mensaje actual.',
    },
    lead_quality: {
      type: 'string',
      enum: ['none', 'low', 'medium', 'high'],
      description: 'Calidad comercial del lead segun intencion, datos y urgencia.',
    },
    customer_type: {
      type: 'string',
      enum: ['unknown', 'b2c', 'contractor', 'b2b', 'returning_customer', 'post_sale', 'complaint'],
      description: 'Tipo de cliente detectado. Usar b2b para constructora, empresa, OC, factura o volumen.',
    },
    lead_class: {
      type: 'string',
      enum: ['none', 'A', 'B', 'C', 'D', 'post_sale', 'complaint', 'general'],
      description: 'Clasificacion comercial Hormiglass. A=alta prioridad, B=oportunidad clara, C=exploratoria, D=B2B.',
    },
    modality: {
      type: 'string',
      enum: ['unknown', 'material', 'pickup', 'delivery', 'installation', 'post_sale', 'claim'],
      description: 'Modalidad principal solicitada: solo material, retiro, despacho, instalacion, postventa o reclamo.',
    },
    sales_stage: {
      type: 'string',
      enum: ['greeting', 'exploration', 'qualification', 'recommendation', 'objection', 'quote', 'agenda', 'confirmation', 'ready_for_sales', 'not_qualified'],
      description: 'Etapa comercial sugerida para la conversacion.',
    },
    buying_intent: {
      type: 'string',
      enum: ['low', 'medium', 'high'],
      description: 'Intencion de compra estimada.',
    },
    urgency: {
      type: 'string',
      enum: ['low', 'medium', 'high'],
      description: 'Urgencia estimada del requerimiento.',
    },
    service: {
      type: 'string',
      description: 'Producto o servicio detectado. Usar cadena vacia si no hay evidencia suficiente.',
    },
    city: {
      type: 'string',
      description: 'Ciudad detectada. Usar cadena vacia si no hay evidencia suficiente.',
    },
    requirement: {
      type: 'string',
      description: 'Necesidad concreta detectada. Usar cadena vacia si no hay evidencia suficiente.',
    },
    missing_fields: {
      type: 'array',
      items: {
        type: 'string',
        enum: ['service', 'city', 'requirement', 'confirmation'],
      },
      description: 'Campos minimos actuales que aun faltan para derivar a ventas.',
    },
    commercial_missing_fields: {
      type: 'array',
      items: {
        type: 'string',
        enum: ['name', 'product', 'commune', 'quantity', 'measurements', 'modality', 'urgency', 'photos', 'terrain', 'access', 'debris_removal', 'company', 'rut', 'contact', 'email', 'oc', 'invoice', 'payment_validation', 'human_review'],
      },
      description: 'Datos comerciales/operativos faltantes segun el PRD Hormiglass.',
    },
    diagnostic_datos: {
      type: 'object',
      additionalProperties: false,
      required: ['pain', 'scope', 'timing', 'obstacle', 'next_step'],
      properties: {
        pain: { type: 'string', description: 'Dolor o resultado que busca el cliente.' },
        scope: { type: 'string', description: 'Alcance: producto, cantidad, medidas, modalidad o uso.' },
        timing: { type: 'string', description: 'Tiempo, urgencia o fecha objetivo.' },
        obstacle: { type: 'string', description: 'Objecion o friccion detectada.' },
        next_step: { type: 'string', description: 'Siguiente microaccion recomendada.' },
      },
    },
    confirmation_status: {
      type: 'string',
      enum: ['none', 'requested', 'confirmed', 'rejected'],
      description: 'Estado de confirmacion explicita de los datos por parte del usuario.',
    },
    should_create_lead: {
      type: 'boolean',
      description: 'Decision conversacional de Hormi Atencion. Solo true con datos completos y confirmacion explicita.',
    },
    needs_confirmation: {
      type: 'boolean',
      description: 'true si falta confirmar datos o si la confianza no permite avanzar.',
    },
    confidence: {
      type: 'number',
      minimum: 0,
      maximum: 1,
      description: 'Confianza global entre 0 y 1.',
    },
    reply_text: {
      type: 'string',
      description: 'Respuesta breve sugerida en espanol neutro.',
    },
    catalog_matches: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          id: { type: 'string' },
          sku: { type: 'string' },
          name: { type: 'string' },
          reason: { type: 'string' },
        },
      },
      description: 'Productos o servicios del catalogo oficial que coinciden con la necesidad.',
    },
    price_context: {
      type: 'object',
      additionalProperties: false,
      properties: {
        type: { type: 'string', enum: ['none', 'fixed', 'reference', 'from', 'range', 'requires_human'] },
        currency: { type: 'string' },
        amount: { type: 'number' },
        amount_min: { type: 'number' },
        amount_max: { type: 'number' },
        unit: { type: 'string' },
        requires_validation: { type: 'boolean' },
        explanation: { type: 'string' },
      },
      description: 'Contexto de precio basado solo en reglas oficiales entregadas.',
    },
    objection_detected: {
      type: 'string',
      enum: ['none', 'price', 'competitor', 'thinking', 'urgency', 'stock', 'discount', 'payment', 'warranty', 'technical', 'other'],
      description: 'Objecion principal detectada, si existe.',
    },
    escalation_area: {
      type: 'string',
      enum: ['none', 'sales', 'b2b', 'finance', 'post_sale', 'claims', 'scheduling', 'management'],
      description: 'Area humana recomendada si corresponde derivar.',
    },
    next_best_action: {
      type: 'string',
      enum: ['ask_data', 'recommend_product', 'answer_question', 'handle_objection', 'quote_reference', 'offer_agenda', 'confirm', 'handoff_sales', 'handoff_b2b', 'handoff_finance', 'handoff_post_sale', 'handoff_claims', 'close_not_qualified'],
      description: 'Siguiente accion recomendada.',
    },
    handoff_reason: {
      type: 'string',
      description: 'Motivo de derivacion a humano si corresponde.',
    },
    executive_summary: {
      type: 'string',
      description: 'Resumen breve y util para la ejecutiva humana, aunque aun no exista lead confirmado.',
    },
    clickup_summary: {
      type: 'string',
      description: 'Resumen corto para ClickUp; vacio si no hay lead confirmado.',
    },
  explicitly_mentioned_fields: {
    type: 'array',
    items: {
      type: 'string',
      enum: ['service', 'city', 'requirement'],
    },
    description: 'Lista de campos que el usuario mencionó EXPLÍCITAMENTE en su mensaje actual. Solo incluir campos con evidencia textual directa. Ej: si usuario dice "es en Valparaíso", solo incluir ["city"]. No incluir campos inferidos o asumidos.',
  },
  },
};

const basePayload = {
  ai_provider: provider,
  ai_model: model,
  ai_base_url: baseUrl,
  ai_api_mode: apiMode,
  ai_context: currentContext,
  response_schema: responseSchema,
  commercial_context: commercialContext,
  commercial_context_counts: commercialContextCounts,
};

const configError = isPlaceholder(directApiKey) || isPlaceholder(model) ? 'missing_api_config' : null;

if (configError) {
  return [{
    json: {
      ...basePayload,
      ai_skipped: false,
      ai_request: null,
      ai_request_error: configError,
      ai_request_path: requestPath,
      ai_timeout_ms: timeoutMs,
    },
  }];
}

const systemPrompt = [
  'Eres Hormi Atencion, la IA oficial del CRM WhatsApp de Hormiglass.',
  'Responde exclusivamente con un objeto JSON valido que cumpla el JSON Schema solicitado.',
  'Tienes autonomia conversacional para entender intencion, extraer datos, decidir el siguiente paso, redactar respuesta y marcar should_create_lead=true cuando corresponda.',
  'n8n y PostgreSQL ejecutan tus decisiones: persistencia, asignacion, ClickUp y auditoria. Tu salida JSON es el contrato operativo.',
  'Reglas obligatorias:',
  '- No inventes datos. Usa cadena vacia cuando no haya evidencia textual o contexto existente suficiente.',
  '- Si confidence es menor a 0.75, no propongas campos nuevos: deja service, city y requirement vacios salvo datos existentes en el contexto.',
  '- should_create_lead solo puede ser true cuando servicio, ciudad, requerimiento y confirmacion explicita esten presentes.',
  '- Si falta confirmacion, usa confirmation_status=requested o none, missing_fields debe incluir confirmation y should_create_lead=false.',
  '- Si el usuario confirma explicitamente datos completos, usa confirmation_status=confirmed e intent=confirmation_yes.',
  '- Si el usuario corrige un dato, usa intent=correction y devuelve solo datos sustentados por el mensaje o contexto.',
  '- reply_text debe ser breve, claro y en espanol; si falta algo, pregunta por el dato faltante.',
  '- clickup_summary debe quedar vacio si el lead no esta confirmado.',
  '- Actua como asesor comercial consultivo: diagnostica antes de cotizar.',
  '- Usa el metodo D.A.T.O.S.: dolor, alcance, tiempo, obstaculo y siguiente paso.',
  '- Clasifica el lead: A alta prioridad/instalacion/proyecto grande/urgencia, B oportunidad clara, C exploratorio/menor, D B2B/empresa/OC/factura/volumen.',
  '- Detecta modalidad: material, retiro, despacho, instalacion, postventa o reclamo.',
  '- Deriva a humano cuando haya B2B, pago, factura, reclamo, garantia, descuento, stock real, instalacion compleja, urgencia alta o solicitud explicita de ejecutiva.',
  '- Puedes usar catalogo y precios publicos solo cuando aparezcan en commercial_context.',
  '- No inventes precios, stock, descuentos, garantias, plazos, despacho, instalacion ni agenda.',
  '- No valides pagos. Ante comprobantes, indica que Finanzas valida acreditacion real.',
  '- Si un precio requiere medidas, stock o validacion, presentalo como referencial y pide los datos faltantes.',
  '- Si el cliente pregunta por condiciones, descuentos, garantia, despacho, instalacion o agenda y no hay fuente oficial en commercial_context, deriva a un vendedor o pide validar con el equipo.',
  '',
  '=== RECONOCIMIENTO DE INTENCIONES ===',
  'Reconoce al menos estas 25 intenciones y 10 adicionales. Usa intent segun corresponda:',
  '- saludo inicial -> greeting',
  '- cotizar producto / saber precio -> quote_request',
  '- consultar precio -> price_inquiry',
  '- consultar despacho -> delivery_inquiry',
  '- consultar instalacion -> installation_inquiry',
  '- consultar stock -> stock_inquiry',
  '- consultar horarios / direccion -> provide_info',
  '- consultar formas de pago -> payment_method',
  '- enviar comprobante de pago -> payment_proof',
  '- solicitar factura -> invoice_request',
  '- consultar garantia -> warranty_inquiry',
  '- reclamo / problema -> complaint',
  '- postventa / seguimiento -> post_sale',
  '- reagendar despacho -> reschedule_delivery',
  '- reagendar instalacion -> reschedule_installation',
  '- solicitud B2B / constructora -> b2b_request',
  '- enviar orden de compra (OC) -> purchase_order',
  '- consultar retiro de escombros -> debris_removal',
  '- consultar retiro en planta -> plant_pickup',
  '- comparar con competencia -> competitor_comparison',
  '- pedir descuento -> discount_request',
  '- cliente antiguo / ya compre antes -> returning_customer',
  '- dejar resena -> review',
  '- hablar con ejecutiva / humano -> talk_to_human',
  '- cliente corrige un dato -> correction',
  '- cliente confirma datos -> confirmation_yes',
  '- cliente rechaza o niega -> confirmation_no',
  '- cliente trae nuevo requerimiento -> new_request',
  '- continuacion de conversacion anterior -> continue_previous',
  '- mensaje irrelevante o sin sentido -> irrelevant',
  '- no se puede determinar -> unknown',
  '',
  '=== DATOS POR TIPO DE SOLICITUD ===',
  'Segun el tipo de solicitud detectado, levanta los campos especificos:',
  '- **Material**: nombre, telefono, producto, cantidad, comuna, retiro/despacho, fecha estimada, tipo cliente.',
  '- **Instalacion**: nombre, telefono, producto, comuna, metros aprox, tipo de terreno, fotos, fecha deseada, retiro de escombros, acceso, tipo lugar.',
  '- **B2B**: empresa, RUT, contacto, cargo, telefono, correo, obra, comuna, producto, cantidad, fecha, OC, condicion pago, documentacion.',
  '- **Despacho**: comuna, direccion, producto, cantidad, fecha tentativa, restricciones acceso, contacto recepcion.',
  '- **Reclamo/Garantia**: nombre, telefono, nro venta, producto, fecha, descripcion, fotos/videos, comuna, urgencia.',
  '- **Pago**: nombre, telefono, monto, medio, comprobante, nro cotizacion o venta.',
  'Usa commercial_missing_fields para marcar cuales faltan.',
  '',
  '=== RETIRO DE ESCOMBROS ===',
  '- Si modalidad = instalacion, pregunta OBLIGATORIAMENTE por retiro de escombros.',
  '- Agrega debris_removal a commercial_missing_fields.',
  '- Advertir que requiere coordinacion logistica adicional.',
  '',
  '=== MANEJO DE OBJECIONES ===',
  'Usa estos scripts segun la objecion detectada (objection_detected):',
  '',
  'Si objection_detected = price ("esta caro", "muy caro", "mucho"):',
  '  Responde: "Entiendo. Es normal comparar. En estos proyectos lo importante es revisar el costo total: producto, espesor, despacho, instalacion, plazo, garantia y respaldo. A veces una opcion mas barata no incluye todo o puede terminar costando mas si despues hay que corregir."',
  '',
  'Si objection_detected = competitor ("en otro lado mas barato", "competencia"):',
  '  Responde: "Perfecto que compares. Solo asegurate de revisar si ambas cotizaciones incluyen lo mismo: material, medidas, espesor, despacho, instalacion, retiro de escombros, plazo y garantia. Si quieres, te ayudo a ordenar la informacion para que una ejecutiva pueda orientarte mejor."',
  '  No iguales precios ni ofrezcas descuento automaticamente.',
  '',
  'Si objection_detected = thinking ("lo voy a pensar", "lo veo", "lo reviso"):',
  '  Responde: "Esta bien. Para ayudarte a decidir, ?que punto te falta resolver: precio, plazo, producto, instalacion o confianza?"',
  '',
  'Si objection_detected = urgency ("necesito rapido", "urgencia", "para ayer"):',
  '  Responde: "Entiendo. Para revisar factibilidad necesitamos comuna, producto, cantidad y si es retiro, despacho o instalacion. Prefiero ayudarte a confirmar un plazo realista antes de prometer algo que pueda fallar."',
  '',
  'Si el cliente dice "solo quiero precio" o "solo precio":',
  '  Responde: "Te entiendo. Para darte un precio correcto necesito al menos producto, cantidad aproximada, comuna y modalidad. No es lo mismo solo material que despacho o instalacion."',
  '',
  '=== FORMATO DE RESUMEN PARA EJECUTIVA ===',
  'Cuando debas derivar a humano o tengas datos suficientes, genera executive_summary con:',
  'Cliente: [nombre]',
  'Telefono: [numero]',
  'Tipo de cliente: [B2C/contratista/B2B/antiguo/reclamo]',
  'Clasificacion: [Lead A/B/C/D]',
  'Producto: [producto]',
  'Modalidad: [material/despacho/retiro/instalacion]',
  'Comuna: [comuna]',
  'Cantidad/medidas: [detalle]',
  'Urgencia: [fecha o nivel]',
  'Dolor/necesidad: [que quiere resolver]',
  'Objecion: [precio/competencia/plazo/confianza/ninguna]',
  'Retiro escombros: [Si/No/No informado]',
  'Fotos: [Si/No]',
  'Requiere factura: [Si/No/No informado]',
  'OC: [Si/No/No aplica]',
  'Siguiente paso: [llamar/cotizar/pedir datos/derivar B2B/revisar pago/revisar reclamo]',
  'Comentario: [resumen breve]',
].join('\n');

const chatContractPrompt = [
  'Contrato JSON obligatorio para Chat Completions:',
  '- Devuelve exactamente un objeto JSON, sin Markdown ni texto extra.',
  '- Incluye siempre estas claves: intent, lead_quality, customer_type, lead_class, modality, service, city, requirement, missing_fields, commercial_missing_fields, diagnostic_datos, confirmation_status, should_create_lead, needs_confirmation, confidence, reply_text, objection_detected, escalation_area, next_best_action, handoff_reason, executive_summary, clickup_summary.',
  '- intent debe ser uno de: greeting, quote_request, provide_info, price_inquiry, delivery_inquiry, installation_inquiry, stock_inquiry, payment_method, payment_proof, invoice_request, warranty_inquiry, complaint, post_sale, reschedule_delivery, reschedule_installation, b2b_request, purchase_order, debris_removal, plant_pickup, competitor_comparison, discount_request, returning_customer, review, talk_to_human, correction, confirmation_yes, confirmation_no, new_request, continue_previous, irrelevant, unknown.',
  '- lead_quality debe ser uno de: none, low, medium, high.',
  '- customer_type debe ser uno de: unknown, b2c, contractor, b2b, returning_customer, post_sale, complaint.',
  '- lead_class debe ser uno de: none, A, B, C, D, post_sale, complaint, general.',
  '- modality debe ser uno de: unknown, material, pickup, delivery, installation, post_sale, claim.',
  '- confirmation_status debe ser uno de: none, requested, confirmed, rejected.',
  '- missing_fields solo puede contener: service, city, requirement, confirmation.',
  '- confidence debe ser un numero entre 0 y 1. Usa al menos 0.8 si el mensaje contiene claramente servicio y ciudad.',
  '- needs_confirmation debe ser true si falta confirmacion explicita.',
  '- should_create_lead solo puede ser true con confirmacion explicita y datos completos.',
  '- Si tienes datos completos pero falta confirmacion, intent=quote_request, confirmation_status=requested, missing_fields=[\'confirmation\'], should_create_lead=false y reply_text debe pedir confirmacion.',
  '- Si recomiendas un producto, usa catalog_matches con id, sku o name presente en commercial_context.catalog_items.',
  '- Si informas precio, usa price_context basado solo en price_rules de commercial_context.catalog_items.',
].join('\n');

const userPrompt = JSON.stringify({
  current_context: currentContext,
  commercial_context_available: hasCommercialContext,
  commercial_context_rules: {
    catalog_and_public_prices_loaded: commercialContextCounts.catalog_items > 0,
    conditions_loaded: commercialContextCounts.conditions > 0,
    faq_loaded: commercialContextCounts.faqs > 0,
    objections_loaded: commercialContextCounts.objections > 0,
    agenda_loaded: commercialContextCounts.available_slots > 0,
    policy: 'Usar solo informacion presente en commercial_context. Si falta una fuente, no inventar y derivar o pedir validacion.'
  },
  required_json_schema: responseSchema,
}, null, 2);
const aiRequest = usesChatCompletions
  ? {
      model,
      messages: [
        { role: 'system', content: systemPrompt + '\n' + chatContractPrompt + '\nDevuelve solo JSON valido. No uses Markdown.' },
        { role: 'user', content: userPrompt },
      ],
      temperature: Number($env.AI_DIRECT_API_TEMPERATURE || 0.05),
      max_tokens: Number($env.AI_DIRECT_API_MAX_TOKENS || 1200),
      ...(provider === 'nvidia' ? {} : { response_format: { type: 'json_object' } }),
    }
  : {
      model,
      input: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
      text: {
        format: {
          type: 'json_schema',
          name: 'hormi_lead_qualification_decision',
          schema: responseSchema,
          strict: true,
        },
      },
      temperature: Number($env.AI_DIRECT_API_TEMPERATURE || 0.05),
      store: false,
    };

return [
  {
    json: {
      ...basePayload,
      ai_skipped: false,
      ai_request: aiRequest,
      ai_request_path: requestPath,
      ai_timeout_ms: timeoutMs,
    },
  },
];

const row = items[0]?.json ?? {};

if (row.ai_skipped) {
  return [{ json: { ...row, ai_status_code: null, ai_response: null, ai_retry_attempts: 0 } }];
}

if (row.ai_request_error || !row.ai_request) {
  return [{
    json: {
      ...row,
      ai_status_code: 0,
      ai_response: { error: { message: row.ai_request_error || 'missing_ai_request' } },
      ai_retry_attempts: 0,
      ai_retry_exhausted: false,
      ai_retry_last_error: row.ai_request_error || 'missing_ai_request',
    },
  }];
}

const retryableStatusCodes = new Set([408, 409, 425, 429, 500, 502, 503, 504]);
const maxAttempts = Number($env.EXTERNAL_HTTP_MAX_ATTEMPTS || 4);
const baseDelayMs = Number($env.EXTERNAL_HTTP_RETRY_BASE_MS || 1000);
const maxDelayMs = Number($env.EXTERNAL_HTTP_RETRY_MAX_MS || 10000);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const retryDelay = (attempt) => Math.min(maxDelayMs, baseDelayMs * Math.pow(2, attempt - 1)) + Math.floor(Math.random() * 250);
const safe = (value, fallback = '') => String(value ?? fallback).trim();
const baseUrl = safe(row.ai_base_url, 'https://api.openai.com/v1').replace(/\/+$/, '');
const path = safe(row.ai_request_path, '/responses');
const url = baseUrl + (path.startsWith('/') ? path : '/' + path);
const directApiKey = safe($env.AI_DIRECT_API_KEY);
const timeoutMs = Number(row.ai_timeout_ms || $env.AI_DIRECT_API_TIMEOUT_MS || 8000);

let lastError = null;

for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (directApiKey) headers.Authorization = 'Bearer ' + directApiKey;

    const response = await helpers.httpRequest({
      method: 'POST',
      url,
      headers,
      body: row.ai_request,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: timeoutMs,
    });

    const statusCode = Number(response.statusCode || 0);
    const shouldRetry = retryableStatusCodes.has(statusCode) && attempt < maxAttempts;
    if (!shouldRetry) {
      return [
        {
          json: {
            ...row,
            ai_status_code: statusCode,
            ai_response: response.body || {},
            ai_retry_attempts: attempt,
            ai_retry_exhausted: retryableStatusCodes.has(statusCode) && attempt >= maxAttempts,
            ai_retry_last_error: null,
          },
        },
      ];
    }
  } catch (error) {
    lastError = error;
    if (attempt >= maxAttempts) {
      return [
        {
          json: {
            ...row,
            ai_status_code: 0,
            ai_response: { error: { message: error.message } },
            ai_retry_attempts: attempt,
            ai_retry_exhausted: true,
            ai_retry_last_error: error.message,
          },
        },
      ];
    }
  }

  await sleep(retryDelay(attempt));
}

return [{ json: { ...row, ai_status_code: 0, ai_response: { error: { message: lastError?.message || 'AI provider retry exhausted' } }, ai_retry_attempts: maxAttempts, ai_retry_exhausted: true, ai_retry_last_error: lastError?.message || null } }];

const row = items[0]?.json ?? {};

const safe = (value, fallback = '') => String(value ?? fallback).trim();
const compactObject = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const clampConfidence = (value) => {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  return Math.max(0, Math.min(1, number));
};
const extractOutputText = (response) => {
  if (!response || typeof response !== 'object') return '';
  if (typeof response.output_text === 'string') return response.output_text;
  if (typeof response.reply === 'string') return response.reply;
  if (response.reply && typeof response.reply === 'object') {
    const replyPayloads = Array.isArray(response.reply.payloads) ? response.reply.payloads : [];
    const replyPayloadText = replyPayloads.map((payload) => safe(payload?.text)).filter(Boolean).join('\\n').trim();
    if (replyPayloadText) return replyPayloadText;
    if (typeof response.reply.finalAssistantVisibleText === 'string') return response.reply.finalAssistantVisibleText;
    if (typeof response.reply.finalAssistantRawText === 'string') return response.reply.finalAssistantRawText;
    return JSON.stringify(response.reply);
  }
  if (typeof response.text === 'string') return response.text;
  if (typeof response.finalAssistantVisibleText === 'string') return response.finalAssistantVisibleText;
  if (typeof response.finalAssistantRawText === 'string') return response.finalAssistantRawText;
  const choices = Array.isArray(response.choices) ? response.choices : [];
  const choiceText = choices.map((choice) => safe(choice?.message?.content, safe(choice?.text))).filter(Boolean).join('\\n').trim();
  if (choiceText) return choiceText;
  const output = Array.isArray(response.output) ? response.output : [];
  const outputText = output.flatMap((entry) => Array.isArray(entry?.content) ? entry.content : [])
    .map((content) => safe(content?.text, safe(content?.output_text)))
    .filter(Boolean)
    .join('\\n')
    .trim();
  if (outputText) return outputText;
  const payloads = Array.isArray(response.payloads) ? response.payloads : [];
  return payloads.map((payload) => safe(payload?.text)).filter(Boolean).join('\\n').trim();
};
const parseStructuredOutput = (value) => {
  const text = safe(value).trim();
  if (!text) throw new Error('empty_output');
  try {
    return JSON.parse(text);
  } catch (_error) {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start < 0 || end <= start) throw new Error('json_object_not_found');
    return JSON.parse(text.slice(start, end + 1));
  }
};
const uniqueMissing = (fields) => [...new Set(fields.filter(Boolean))];
const requiredMissingFromFields = (fields) => ['service', 'city', 'requirement'].filter((field) => !safe(fields[field]));

const commercialContext = compactObject(row.commercial_context);
const commercialItems = Array.isArray(commercialContext.catalog_items) ? commercialContext.catalog_items : [];
const commercialContextCounts = compactObject(row.commercial_context_counts);
const catalogKeys = new Set(commercialItems.flatMap((item) => [item?.id, item?.sku, item?.name].map((value) => safe(value).toLowerCase()).filter(Boolean)));
const hasOfficialPriceRules = commercialItems.some((item) => Array.isArray(item?.price_rules) && item.price_rules.length > 0);
const filterCatalogMatches = (matches) => {
  if (!Array.isArray(matches)) return [];
  return matches
    .filter((match) => {
      const keys = [match?.id, match?.sku, match?.name].map((value) => safe(value).toLowerCase()).filter(Boolean);
      return keys.some((key) => catalogKeys.has(key));
    })
    .slice(0, 5)
    .map((match) => ({
      id: safe(match.id),
      sku: safe(match.sku),
      name: safe(match.name),
      reason: safe(match.reason),
    }));
};
const sanitizePriceContext = (value) => {
  const payload = compactObject(value);
  if (!hasOfficialPriceRules || Object.keys(payload).length === 0) {
    return { type: 'none', requires_validation: true, explanation: '' };
  }
  const allowedTypes = new Set(['none', 'fixed', 'reference', 'from', 'range', 'requires_human']);
  const numberOrNull = (input) => {
    const number = Number(input);
    return Number.isFinite(number) ? number : null;
  };
  return {
    type: allowedTypes.has(payload.type) ? payload.type : 'reference',
    currency: safe(payload.currency, 'CLP'),
    amount: numberOrNull(payload.amount),
    amount_min: numberOrNull(payload.amount_min),
    amount_max: numberOrNull(payload.amount_max),
    unit: safe(payload.unit),
    requires_validation: payload.requires_validation !== false,
    explanation: safe(payload.explanation),
  };
};

const existing = row.ai_context?.existing_fields || {};
const safeExisting = {
  service: safe(existing.service),
  city: safe(existing.city),
  requirement: safe(existing.requirement),
};
const fallbackMissing = requiredMissingFromFields(safeExisting);
const fallbackResult = {
  intent: 'unknown',
  service: safeExisting.service,
  city: safeExisting.city,
  requirement: safeExisting.requirement,
  missing_fields: fallbackMissing,
  confirmation_status: 'none',
  should_create_lead: false,
  needs_confirmation: true,
  confidence: 0,
  reply_text: '',
  clickup_summary: '',
  customer_type: 'unknown',
  lead_class: 'none',
  modality: 'unknown',
  diagnostic_datos: { pain: '', scope: '', timing: '', obstacle: '', next_step: '' },
  commercial_missing_fields: [],
  objection_detected: 'none',
  escalation_area: 'none',
  catalog_matches: [],
  price_context: { type: 'none', requires_validation: true, explanation: '' },
  next_best_action: 'ask_data',
  handoff_reason: '',
  executive_summary: '',
};

let parsed = fallbackResult;
let outputText = '';
let parseError = null;
const statusCode = Number(row.ai_status_code || 0);
const responseOk = !row.ai_skipped && statusCode >= 200 && statusCode < 300;

if (responseOk) {
  outputText = extractOutputText(row.ai_response);
  try {
    parsed = parseStructuredOutput(outputText);
  } catch (error) {
    parseError = error.message;
    parsed = fallbackResult;
  }
}

const allowedIntent = new Set(['greeting', 'quote_request', 'provide_info', 'correction', 'confirmation_yes', 'confirmation_no', 'new_request', 'continue_previous', 'irrelevant', 'unknown']);
const allowedMissing = new Set(['service', 'city', 'requirement', 'confirmation']);
const allowedCommercialMissing = new Set(['name', 'product', 'commune', 'quantity', 'measurements', 'modality', 'urgency', 'photos', 'terrain', 'access', 'debris_removal', 'company', 'rut', 'contact', 'email', 'oc', 'invoice', 'payment_validation', 'human_review']);
const allowedConfirmation = new Set(['none', 'requested', 'confirmed', 'rejected']);
const allowedCustomerType = new Set(['unknown', 'b2c', 'contractor', 'b2b', 'returning_customer', 'post_sale', 'complaint']);
const allowedLeadClass = new Set(['none', 'A', 'B', 'C', 'D', 'post_sale', 'complaint', 'general']);
const allowedModality = new Set(['unknown', 'material', 'pickup', 'delivery', 'installation', 'post_sale', 'claim']);
const allowedObjection = new Set(['none', 'price', 'competitor', 'thinking', 'urgency', 'stock', 'discount', 'payment', 'warranty', 'technical', 'other']);
const allowedEscalationArea = new Set(['none', 'sales', 'b2b', 'finance', 'post_sale', 'claims', 'scheduling', 'management']);
const sanitizeDatos = (value) => {
  const payload = compactObject(value);
  return {
    pain: safe(payload.pain),
    scope: safe(payload.scope),
    timing: safe(payload.timing),
    obstacle: safe(payload.obstacle),
    next_step: safe(payload.next_step),
  };
};

const confidence = clampConfidence(parsed.confidence);
const canAcceptModelFields = responseOk && !parseError && confidence >= 0.75;
const modelFields = {
  service: safe(parsed.service),
  city: safe(parsed.city),
  requirement: safe(parsed.requirement),
};
const acceptedFields = canAcceptModelFields
  ? {
      service: modelFields.service || safeExisting.service,
      city: modelFields.city || safeExisting.city,
      requirement: modelFields.requirement || safeExisting.requirement,
    }
  : safeExisting;
const rejectedLowConfidenceFields = !canAcceptModelFields && Boolean(modelFields.service || modelFields.city || modelFields.requirement);

const parsedMissingFields = Array.isArray(parsed.missing_fields)
  ? parsed.missing_fields.filter((field) => allowedMissing.has(field))
  : [];
const commercialMissingFields = Array.isArray(parsed.commercial_missing_fields)
  ? uniqueMissing(parsed.commercial_missing_fields.filter((field) => allowedCommercialMissing.has(field)))
  : [];
const confirmationStatus = allowedConfirmation.has(parsed.confirmation_status)
  ? parsed.confirmation_status
  : parsedMissingFields.includes('confirmation') || parsed.needs_confirmation ? 'requested' : 'none';
const confirmationSatisfied = confirmationStatus === 'confirmed' && parsed.intent === 'confirmation_yes';
const baseMissingFields = requiredMissingFromFields(acceptedFields);
const missingFields = uniqueMissing([
  ...baseMissingFields,
  ...parsedMissingFields.filter((field) => field === 'confirmation' || baseMissingFields.includes(field)),
  ...(confirmationSatisfied ? [] : ['confirmation']),
]);
const hasRequiredLeadFields = Boolean(acceptedFields.service && acceptedFields.city && acceptedFields.requirement);
const modelShouldCreateLead = Boolean(parsed.should_create_lead);
const guardedShouldCreateLead = modelShouldCreateLead && hasRequiredLeadFields && confirmationSatisfied && confidence >= 0.75 && !parseError;
const fallbackReason = row.ai_request_error
  ? row.ai_request_error
  : row.ai_skipped
    ? row.ai_skip_reason || 'skipped'
    : !responseOk
      ? 'provider_error'
      : parseError
        ? 'invalid_json'
        : confidence < 0.75
          ? 'low_confidence'
          : null;
const provider = safe(row.ai_provider, 'direct_api');
const apiMode = safe(row.ai_api_mode, 'openai_responses');
const catalogMatches = canAcceptModelFields ? filterCatalogMatches(parsed.catalog_matches) : [];
const priceContext = canAcceptModelFields ? sanitizePriceContext(parsed.price_context) : { type: 'none', requires_validation: true, explanation: '' };
const allowedSalesStage = new Set(['greeting', 'exploration', 'qualification', 'recommendation', 'objection', 'quote', 'agenda', 'confirmation', 'ready_for_sales', 'not_qualified']);
const allowedBuyingIntent = new Set(['low', 'medium', 'high']);
const allowedUrgency = new Set(['low', 'medium', 'high']);
const allowedNextAction = new Set(['ask_data', 'recommend_product', 'answer_question', 'handle_objection', 'quote_reference', 'offer_agenda', 'confirm', 'handoff_sales', 'handoff_b2b', 'handoff_finance', 'handoff_post_sale', 'handoff_claims', 'close_not_qualified']);
const customerType = allowedCustomerType.has(parsed.customer_type) ? parsed.customer_type : 'unknown';
const leadClass = allowedLeadClass.has(parsed.lead_class) ? parsed.lead_class : 'none';
const modality = allowedModality.has(parsed.modality) ? parsed.modality : 'unknown';
const objectionDetected = allowedObjection.has(parsed.objection_detected) ? parsed.objection_detected : 'none';
const escalationArea = allowedEscalationArea.has(parsed.escalation_area) ? parsed.escalation_area : 'none';
const diagnosticDatos = sanitizeDatos(parsed.diagnostic_datos);

return [
  {
    json: {
      ai_skipped: Boolean(row.ai_skipped),
      ai_skip_reason: row.ai_skip_reason || null,
      ai_provider: provider,
      ai_model: row.ai_model || null,
      ai_api_mode: apiMode,
      ai_status_code: row.ai_status_code || null,
      ai_retry_attempts: row.ai_retry_attempts || 0,
      ai_retry_exhausted: Boolean(row.ai_retry_exhausted),
      ai_parse_error: parseError,
      ai_request_error: row.ai_request_error || null,
      ai_fallback_reason: fallbackReason,
      intent: allowedIntent.has(parsed.intent) ? parsed.intent : 'unknown',
      lead_quality: ['none', 'low', 'medium', 'high'].includes(parsed.lead_quality) ? parsed.lead_quality : 'none',
      customer_type: customerType,
      lead_class: leadClass,
      modality,
      sales_stage: allowedSalesStage.has(parsed.sales_stage) ? parsed.sales_stage : null,
      buying_intent: allowedBuyingIntent.has(parsed.buying_intent) ? parsed.buying_intent : null,
      urgency: allowedUrgency.has(parsed.urgency) ? parsed.urgency : null,
      service: acceptedFields.service,
      city: acceptedFields.city,
      requirement: acceptedFields.requirement,
      missing_fields: missingFields,
      commercial_missing_fields: commercialMissingFields,
      diagnostic_datos: diagnosticDatos,
      confirmation_status: confirmationStatus,
      should_create_lead: guardedShouldCreateLead,
      model_should_create_lead_raw: modelShouldCreateLead,
      needs_confirmation: Boolean(parsed.needs_confirmation || !guardedShouldCreateLead),
      confidence,
      reply_text: canAcceptModelFields ? safe(parsed.reply_text) : '',
      clickup_summary: guardedShouldCreateLead ? safe(parsed.clickup_summary) : '',
      catalog_matches: catalogMatches,
      price_context: priceContext,
      objection_detected: objectionDetected,
      escalation_area: escalationArea,
      next_best_action: allowedNextAction.has(parsed.next_best_action) ? parsed.next_best_action : null,
      handoff_reason: safe(parsed.handoff_reason),
      executive_summary: safe(parsed.executive_summary),
      metadata_json: JSON.stringify({
        provider,
        model: row.ai_model || null,
        api_mode: apiMode,
        status_code: row.ai_status_code || null,
        retry_attempts: row.ai_retry_attempts || 0,
        retry_exhausted: Boolean(row.ai_retry_exhausted),
